#!/bin/bash
sed -i 's/let coords = getCoordinates(e);/let coords = getCoordinates(e);\n    if (coords && activeCollaborationId && user) {\n      const now = Date.now();\n      if (now - lastCursorUpdateRef.current > 100) {\n        lastCursorUpdateRef.current = now;\n        setDoc(doc(db, `collaborations\/${activeCollaborationId}\/cursors`, user.uid), {\n          uid: user.uid,\n          name: user.displayName || "Usuário",\n          x: coords.x,\n          y: coords.y,\n          color: color,\n          size: brushSize,\n          tool: tool,\n          timestamp: serverTimestamp(),\n        }, { merge: true }).catch(() => {});\n      }\n    }/g' src/components/CanvasArea.tsx
